  display: block;
  color: #173445;
}

.customer-bookings {
  max-width: 1050px;
  margin: 2rem auto;
  padding: 1.5rem;
}

.page-heading, .card-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.page-heading {
  margin-bottom: 1.8rem;
}

h1 {
  font-size: 2rem;
  margin: 0.4rem 0;
}

h2 {
  font-size: 1.35rem;
}

h3 {
  margin: 0.3rem 0;
}

.eyebrow {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 700;
  color: #617481;
}

.booking-card {
  background: #fff;
  border: 1px solid #dce3e5;
  border-radius: 16px;
  padding: 1.5rem;
  margin: 1.2rem 0;
  box-shadow: 0 4px 16px rgba(20, 51, 68, 0.0196078431);
}

.detail {
  border-color: #b5c8ce;
}

.reference {
  font-family: monospace;
  font-size: 0.8rem;
  overflow-wrap: anywhere;
  color: #64747a;
}

.price {
  font-size: 1.3rem;
  font-weight: 700;
}

.status {
  display: inline-block;
  border-radius: 20px;
  padding: 0.35rem 0.7rem;
  background: #fff0d5;
  font-size: 0.8rem;
  white-space: nowrap;
}

.status.confirmed {
  background: #e1f3e9;
  color: #186142;
}

.reservation-status-steps, .actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin: 1rem 0;
}

.reservation-status-steps span {
  font-size: 0.75rem;
  background: #f1f3f4;
  border-radius: 5px;
  padding: 0.4rem 0.6rem;
}

.reservation-status-steps .done {
  background: #e1f3e9;
  color: #186142;
}

button {
  padding: 0.7rem 1rem;
  border: 1px solid #cbd5da;
  border-radius: 8px;
  background: #fff;
  color: #173445;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
}

button.primary {
  background: #153748;
  color: #fff;
  border-color: #153748;
}

button:disabled {
  opacity: 0.55;
  cursor: wait;
}

button:hover:not(:disabled) {
  filter: brightness(0.95);
}

.notice {
  border-radius: 9px;
  background: #edf4f7;
  padding: 0.9rem 1rem;
  font-size: 0.9rem;
  line-height: 1.5;
}

.notice.error {
  background: #fff0eb;
  color: #a63821;
}

.help {
  font-size: 0.85rem;
  color: #657780;
  line-height: 1.6;
}

.amounts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.8rem;
  margin: 1.4rem 0;
}

.amounts > div {
  padding: 1rem;
  background: #f6f8f8;
  border-radius: 9px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.amounts span, .amounts small {
  font-size: 0.75rem;
  color: #657780;
}

.amounts strong {
  font-size: 1.05rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  font-size: 0.85rem;
  margin-bottom: 1rem;
}

input, textarea {
  min-width: 0;
  box-sizing: border-box;
  padding: 0.75rem;
  border: 1px solid #cbd5da;
  border-radius: 7px;
  font: inherit;
  background: #fff;
  color: #173445;
}

input:disabled {
  background: #f0f3f4;
  color: #74828a;
}

.check {
  flex-direction: row;
  align-items: center;
}

.check input {
  width: auto;
}

.edit-form {
  padding-top: 1rem;
  border-top: 1px solid #e1e7e9;
}

.payment-panel {
  border: 2px solid #b3c9d2;
}

.payment-element {
  margin: 1.5rem 0;
  min-height: 80px;
}

summary {
  cursor: pointer;
  font-weight: 700;
}

@media (max-width: 700px) {
  .customer-bookings {
    padding: 1rem;
  }
  .booking-card {
    padding: 1.1rem;
  }
  .page-heading, .card-heading {
    align-items: flex-start;
  }
  .amounts {
    grid-template-columns: repeat(2, 1fr);
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .actions button {
    flex: 1 1 140px;
  }
  h1 {
    font-size: 1.7rem;
  }
}
/* Keep status badges independent of framework progress-bar styles. */
.reservation-status-steps {
  height: auto;
  min-height: 0;
  overflow: visible;
  background: transparent;
  line-height: 1.5;
  align-items: flex-start;
}

.reservation-status-steps > span {
  display: inline-block;
  max-width: 100%;
  box-sizing: border-box;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.5;
  flex: 0 1 auto;
